	breach_session_no INTEGER DEFAULT '1' NOT NULL, 
	status VARCHAR(16) DEFAULT 'pending' NOT NULL, 
	suppression_reason VARCHAR(40), 
	escalation VARCHAR(20), 
	impression_count INTEGER DEFAULT '0' NOT NULL, 
	first_shown_at TIMESTAMP WITH TIME ZONE, 
	last_shown_at TIMESTAMP WITH TIME ZONE, 
	action VARCHAR(20), 
	acted_at TIMESTAMP WITH TIME ZONE, 
	id UUID DEFAULT gen_random_uuid() NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_cap2_alert_events PRIMARY KEY (id), 
	CONSTRAINT uq_cap2_alert_events_user_type_trigger UNIQUE (user_id, alert_type, trigger_key), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_type CHECK (alert_type IN ('nhoi_lenh', 'cham_cat_lo')), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_status CHECK (status IN ('pending', 'shown', 'suppressed', 'acted')), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_escalation CHECK (escalation IS NULL OR escalation IN ('normal', 'delay_5s', 'type_phrase')), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_action CHECK (action IS NULL OR action IN ('cancel_buy', 'proceed_buy', 'sell_ato', 'hold', 'position_closed')), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_impressions_nonnegative CHECK (impression_count >= 0), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_breach_session_positive CHECK (breach_session_no >= 1), 
	CONSTRAINT ck_cap2_alert_events_cap2_alert_event_draft_shape CHECK ((intended_quantity IS NULL AND intended_order_type IS NULL AND intended_limit_price_vnd IS NULL) OR (intended_quantity IS NOT NULL AND intended_quantity > 0 AND intended_order_type IS NOT NULL AND ((intended_order_type = 'market' AND intended_limit_price_vnd IS NULL) OR (intended_order_type = 'limit' AND intended_limit_price_vnd IS NOT NULL AND intended_limit_price_vnd > 0)))), 
