	price_source VARCHAR(50) NOT NULL, 
	price_time TIMESTAMP WITH TIME ZONE NOT NULL, 
	traded_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	id UUID DEFAULT gen_random_uuid() NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_virtual_trades PRIMARY KEY (id), 
	CONSTRAINT fk_virtual_trades_order_id_virtual_orders FOREIGN KEY(order_id) REFERENCES virtual_orders (id) ON DELETE CASCADE, 
	CONSTRAINT fk_virtual_trades_account_id_virtual_trading_accounts FOREIGN KEY(account_id) REFERENCES virtual_trading_accounts (id) ON DELETE CASCADE
);

CREATE INDEX ix_virtual_trades_account_id ON virtual_trades (account_id);

CREATE INDEX ix_virtual_trades_order_id ON virtual_trades (order_id);

CREATE TABLE bot_decisions (
	bot_run_id UUID NOT NULL, 
	idempotency_key VARCHAR(180) NOT NULL, 
	symbol VARCHAR(10), 
	action VARCHAR(8) NOT NULL, 
	reason_code VARCHAR(64) NOT NULL, 
	reason VARCHAR(1000) NOT NULL, 
	filter_ids JSONB DEFAULT '[]'::jsonb NOT NULL, 
	rank_tuple JSONB, 
	data_refs JSONB DEFAULT '{}'::jsonb NOT NULL, 
	budget_vnd BIGINT, 
	proposed_qty INTEGER, 
	threshold_vnd NUMERIC(20, 4), 
	execution_id UUID, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	id UUID DEFAULT gen_random_uuid() NOT NULL, 
	CONSTRAINT pk_bot_decisions PRIMARY KEY (id), 
	CONSTRAINT uq_bot_decision_idempotency UNIQUE (idempotency_key), 
	CONSTRAINT ck_bot_decisions_bot_decision_action CHECK (action IN ('buy', 'sell', 'hold', 'skip')), 
	CONSTRAINT fk_bot_decisions_bot_run_id_bot_run_receipts FOREIGN KEY(bot_run_id) REFERENCES bot_run_receipts (id) ON DELETE CASCADE, 
	CONSTRAINT fk_bot_decisions_execution_id_bot_executions FOREIGN KEY(execution_id) REFERENCES bot_executions (id) ON DELETE SET NULL
);

CREATE INDEX ix_bot_decisions_bot_run_id ON bot_decisions (bot_run_id);

CREATE INDEX ix_bot_decisions_symbol ON bot_decisions (symbol);

CREATE TABLE cap2_alert_impressions (
	event_id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	session_date DATE NOT NULL, 
	escalation VARCHAR(20) NOT NULL, 
	shown_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	id UUID DEFAULT gen_random_uuid() NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_cap2_alert_impressions PRIMARY KEY (id), 
	CONSTRAINT uq_cap2_alert_impressions_event_date UNIQUE (event_id, session_date), 
	CONSTRAINT ck_cap2_alert_impressions_cap2_alert_impression_escalation CHECK (escalation IN ('normal', 'delay_5s', 'type_phrase')), 
	CONSTRAINT fk_cap2_alert_impressions_event_id_cap2_alert_events FOREIGN KEY(event_id) REFERENCES cap2_alert_events (id) ON DELETE CASCADE, 
	CONSTRAINT fk_cap2_alert_impressions_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_cap2_alert_impressions_event_id ON cap2_alert_impressions (event_id);

CREATE INDEX ix_cap2_alert_impressions_user_id ON cap2_alert_impressions (user_id);

CREATE INDEX ix_cap2_alert_impressions_user_session ON cap2_alert_impressions (user_id, session_date);

CREATE TABLE virtual_settlements (
	account_id UUID NOT NULL, 
	trade_id UUID NOT NULL, 
	kind vt_settlement_kind NOT NULL, 
	amount BIGINT NOT NULL, 
	symbol VARCHAR(10), 
	due_date DATE NOT NULL, 
	status vt_settlement_status DEFAULT 'pending' NOT NULL, 
	settled_at TIMESTAMP WITH TIME ZONE, 
	id UUID DEFAULT gen_random_uuid() NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_virtual_settlements PRIMARY KEY (id), 
	CONSTRAINT fk_virtual_settlements_account_id_virtual_trading_accounts FOREIGN KEY(account_id) REFERENCES virtual_trading_accounts (id) ON DELETE CASCADE, 
	CONSTRAINT fk_virtual_settlements_trade_id_virtual_trades FOREIGN KEY(trade_id) REFERENCES virtual_trades (id) ON DELETE CASCADE
);

CREATE INDEX ix_virtual_settlements_account_id ON virtual_settlements (account_id);

CREATE INDEX ix_virtual_settlements_due_date ON virtual_settlements (due_date);
